def lcs_of_three(X, Y, Z):
    # Create a 3D DP table to store lengths of longest common suffixes
    dp = [[[0] * (len(Z) + 1) for _ in range(len(Y) + 1)] for _ in range(len(X) + 1)]

    # Build the dp table from bottom up
    for i in range(1, len(X) + 1):
        for j in range(1, len(Y) + 1):
            for k in range(1, len(Z) + 1):
                if X[i - 1] == Y[j - 1] == Z[k - 1]:
                    dp[i][j][k] = dp[i - 1][j - 1][k - 1] + 1
                else:
                    dp[i][j][k] = max(dp[i - 1][j][k], dp[i][j - 1][k], dp[i][j][k - 1])

    # The length of the longest common subsequence is stored in dp[len(X)][len(Y)][len(Z)]
    return dp[len(X)][len(Y)][len(Z)]

# Example usage:
