from math import comb

def get_total_number_of_sequences(m, n):
    # Initialize a DP table where dp[i][j] represents the number of sequences of length i ending with j
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: There's one way to form a sequence of length 1 with any number from 1 to m
    for i in range(1, m + 1):
        dp[1][i] = 1

    # Fill the DP table
    for length in range(2, n + 1):
        for end in range(1, m + 1):
            for prev in range(1, end // 2 + 1):
                if prev * 2 <= end <= m:
                    dp[length][end] += dp[length - 1][prev]

    # The total number of sequences of length n is the sum of all sequences ending with numbers from 1 to m
    return sum(dp[n])

# Example usage:
print(get_total_number_of_sequences(5, 3))  # Output: 10

